import yaml, json
spec = yaml.safe_load(open('openapi/upstream/v1.yaml'))
paths = spec.get('paths', {})
for p in ['/files', '/files/remote', '/files/remoteLink']:
    if p in paths:
        for method, op in paths[p].items():
            if method in ('post','put'):
                print(p, method.upper(), op.get('operationId'))
                rb = op.get('requestBody', {})
                content = rb.get('content', {})
                for ct, media in content.items():
                    print('  content-type:', ct)
                    props = media.get('schema',{}).get('properties',{})
                    print('  form fields:', json.dumps(list(props.keys())))
EOF
